const input = $json;
const message = input.message_context ?? input.messageContext ?? {};
const snapshot = input.state_snapshot ?? input.stateSnapshot ?? {};
const contacts = Array.isArray(snapshot.contact_candidates) ? snapshot.contact_candidates : [];
const events = Array.isArray(snapshot.event_candidates) ? snapshot.event_candidates : [];
const category = snapshot.contact_category ?? contacts[0]?.contact_category ?? 'unknown';
const noncommercialCategories = new Set(['vendor','venue','staff','personal','institution','automated']);
const result = {
  contract_version: '1.0.0',
  correlation_id: message.correlation_id ?? input.correlation_id ?? null,
  contact_context: {
    status: 'unresolved',
    contact_id: null,
    contact_category: category
  },
  event_context: {
    status: 'unresolved',
    customer_event_id: null,
    commercial_stage: null,
    operational_stage: null,
    stage_version: null,
    human_lock: Boolean(snapshot.human_lock)
  },
  requested_actions: [],
  blockers: []
};

if (noncommercialCategories.has(category) || snapshot.noncommercial === true) {
  result.contact_context.status = 'noncommercial';
  result.event_context.status = 'not_applicable';
  return { json: result };
}

if (contacts.length > 1) {
  result.contact_context.status = 'human_required';
  result.blockers.push('IDENTITY_AMBIGUOUS');
  result.requested_actions.push({ action: 'CREATE_HUMAN_TASK', reason_code: 'IDENTITY_AMBIGUOUS' });
  return { json: result };
}

if (contacts.length === 1) {
  result.contact_context.status = 'resolved';
  result.contact_context.contact_id = contacts[0].contact_id ?? contacts[0].id ?? null;
} else {
  result.contact_context.status = 'needs_create';
  result.requested_actions.push({ action: 'CREATE_CONTACT' });
}

const activeEvents = events.filter((event) => !['closed','cancelled','completed'].includes(String(event.status ?? '').toLowerCase()));
if (activeEvents.length > 1) {
  result.event_context.status = 'human_required';
  result.blockers.push('ACTIVE_EVENT_AMBIGUOUS');
  result.requested_actions.push({ action: 'CREATE_HUMAN_TASK', reason_code: 'ACTIVE_EVENT_AMBIGUOUS' });
  return { json: result };
}

if (activeEvents.length === 1) {
  const event = activeEvents[0];
  result.event_context.status = 'resolved';
  result.event_context.customer_event_id = event.customer_event_id ?? event.id ?? null;
  result.event_context.commercial_stage = event.commercial_stage ?? 'PRE_QUOTE';
  result.event_context.operational_stage = event.operational_stage ?? 'NOT_STARTED';
  result.event_context.stage_version = event.stage_version ?? 0;
} else {
  result.event_context.status = 'needs_create';
  result.event_context.commercial_stage = 'PRE_QUOTE';
  result.event_context.operational_stage = 'NOT_STARTED';
  result.event_context.stage_version = 0;
  result.requested_actions.push({ action: 'CREATE_CUSTOMER_EVENT' });
}

if (result.event_context.human_lock) {
  result.blockers.push('HUMAN_LOCK_ACTIVE');
}

return { json: result };
